  /**
   * Settle a task: the crewmate stops, the worktree and branch go, the
   * lane and open cards retire, and the RECORD CLOSES - its row, timeline
   * and session JSONL under crewmates/<taskId> stay (captain decision D2:
   * "the sessions are very valuable ... we shouldn't remove the entire
   * session JSONL altogether"). The worktree vanishing is the externally
   * observable "settled" signal (the phase3 e2e polls for it), so the
   * record closes before it goes.
   */
  async closeTask(
    taskId: string,
    close: {
      status: "done" | "dropped";
      reason: "landed" | "merged" | "discarded" | "cancelled";
      actor: "captain" | "firstmate" | "host";
      text?: string;
      delivery?: { landedMode: "fast-forward" | "merge" | "pr"; landedAt: number };
    },
  ): Promise<void> {
    this.options.killJobs?.(taskId);
    const runtime = this.tasks.get(taskId);
    if (runtime) {
      runtime.cancelled = true;
      await runtime.transport?.abort().catch(() => {});
      runtime.unsubscribe?.();
      runtime.transport?.dispose();
      this.tasks.delete(taskId);
    }
    const record = this.options.tasks.get(taskId);
    if (record) {
      this.options.tasks.close(taskId, {
        status: close.status,
        reason: close.reason,
        actor: close.actor,
        ...(close.text ? { text: close.text } : {}),
        ...(close.delivery ? { delivery: close.delivery } : {}),
      });
    }
    this.retireTaskCards(taskId, close.reason);
    // The lane retires with its task: a settled task makes any
    // still-recorded guidance moot.
    this.options.inbox.deleteFor(taskId);
    this.scheduleCardBroadcast();
    this.broadcastCrewCounts();
    if (record?.worktreeDir && record.workspaceState !== "removed") {
      await this.options.workspace.removeTaskWorktree({
        taskId,
        cwd: record.worktreeDir,
        branch: record.branch,
        repoDir: record.repoDir,
      });
      this.options.tasks.markWorkspaceRemoved(taskId);
    }
    // Any close may release a row waiting on this task, or leave one
    // waiting forever (the ready query and the dead-blocker card, P2).
    void this.sweepGates(Date.now());
  }

  /** A settled task's open cards resolve out of the stack; the rows stay. */
  private retireTaskCards(taskId: string, reason: string): void {
    for (const [cardId, card] of this.cards) {
      if (card.taskId !== taskId) continue;
      this.cards.delete(cardId);
      this.options.cardStore.resolve(cardId, reason);
    }
  }

  /** The record side of finish(): the wire status mapped onto the record. */
  private closeRecord(
    taskId: string,
    status: "completed" | "cancelled" | "failed",
    error: string | undefined,
    actor: "captain" | "firstmate" | "host",
  ): void {
    if (status === "completed") {
      this.options.tasks.close(taskId, { status: "delivered", reason: "finished", actor });
    } else if (status === "cancelled") {
      this.options.tasks.close(taskId, { status: "dropped", reason: "cancelled", actor });
    } else {
      this.options.tasks.close(taskId, {
        status: "dropped",
        reason: "failed",
        actor,
        ...(error ? { error } : {}),
      });
    }
  }

  /**
   * A session event or a running background job means the crewmate is alive:
   * reset the quiet escalation, and retire a quiet card whose question just
   * answered itself.
   */
  private noteTaskActivity(task: TaskRuntime): void {
    task.lastEventAt = Date.now();
    if (task.quietLevel === 0) return;
    task.quietLevel = 0;
    const quietCardId = `card-quiet-${task.id}`;
    if (this.cards.has(quietCardId)) {
      this.cards.delete(quietCardId);
      this.options.cardStore.resolve(quietCardId, "activity-resumed");
      this.scheduleCardBroadcast();
    }
  }

  /** External activity proof for a task (a running R2 job reporting in). */
  taskActivity(taskId: string): void {
