import { type FeedLine, reportSummary, taskFeedKind } from "@shared/feed";
import type { ActivityStore } from "../storage/activityStore";
import type { TaskEvent } from "../storage/taskEventStore";
import type { TaskRecord } from "../storage/taskStore";
import type { TaskService } from "./taskService";

/**
 * The feed as a view over the task record (task-system design section 11,
 * P3). A feed-worthy timeline event (`task_events.feed = 1`) becomes one
 * feed line authored HERE from the event and its record, in one place for
 * both carriers: the live `task_event` FmEvent the core emits after the
 * commit, and `fm:feed:recent`, which reads the same rows back. The few
 * task-less lines (the captain's own turn, a note, a fleet operation, the
 * Firstmate's failed turn) still persist through `activity_events`; the
 * two are merged by time.
 *
 * The wording keeps the lines the feed has always shown - "crewmate 1
 * spawned - title", "crewmate 1 reported - title: summary", "work landed
 * (fast-forward) - title", "crewmate decommissioned - title completed" -
 * now derived from the record instead of from a runtime event, so the feed
 * cannot say something the record does not.
 */

/** What a feed line needs from the record beside the event. */
export type FeedSubject = Pick<TaskRecord, "key" | "title" | "assignee" | "delivery">;

function text(value: unknown): string | undefined {
  return typeof value === "string" && value.trim() ? value : undefined;
}

/** The feed line for one timeline event, or null when it stays off the feed. */
export function taskFeedLine(record: FeedSubject, event: TaskEvent): FeedLine | null {
  if (!event.feed) return null;
  const data = event.data ?? {};
  const title = record.title;
  const assignee = text(data.assignee) ?? record.assignee ?? "crewmate";
  const status = text(data.status);
  let line: string;
  switch (event.kind) {
    case "dispatched":
      line = `${assignee} spawned - ${title}`;
      break;
    case "report": {
      const summary = text(data.summary) ?? reportSummary(event.text);
      line = summary
        ? `${assignee} reported - ${title}: ${summary}`
        : `${assignee} reported - ${title}`;
      break;
    }
    case "failed": {
      const error = reportSummary(text(data.error) ?? event.text) || "unknown error";
      // A turn that failed on a task that lives on (recordTurnFailure marks
      // it non-fatal) reads differently from a task that failed for good.
      line =
        data.fatal === false
          ? `${assignee}'s turn failed on "${title}" - ${error}`
          : `task failed - ${error}`;
      break;
    }
    case "landed":
      line = `work landed (${record.delivery?.landedMode ?? "merge"}) - ${title}`;
      break;
    case "status": {
      const reason = text(data.reason);
      if (reason === "finished") {
        line = `crewmate decommissioned - ${title} completed`;
      } else if (reason === "cancelled" && record.assignee) {
        line = `crewmate decommissioned - ${title} cancelled`;
      } else {
        line = `${event.text} - ${title}`;
      }
      break;
    }
    default:
      line = `${event.text} - ${title}`;
  }
