        ct = c.get('type') or c.get('kind')
        if ct in ('text','output_text','input_text'):
            parts.append(f"{ct}:{(c.get('text') or '')[:250].replace(chr(10),' ')}")
        elif ct in ('tool_use','function_call','toolCall'):
            name = c.get('name') or c.get('toolName')
