/**
 * Cancel on an idle crewmate that already reported is a decommission, not
 * an abort of unfinished work. Firstmate often tears down idle tasks after
 * a merge via interrupt_crewmate cancel.
 */
private idleCancelStatus(task: TaskRuntime): "completed" | "cancelled" {
  return task.lastCompleteText.trim() ? "completed" : "cancelled";
}

it("decommissions an idle reported task as completed when cancelled", async () => {
  const crewmate = fakeCrewmate();
  const { supervisor, events, tasks } = setup(crewmate);
  const { taskId } = await supervisor.commission({
    title: "Ship it",
    intent: intentOf("open the pr"),
  });
  await tick();
  crewmate.emit({ type: "assistant_delta", taskId, text: "PR opened." });
  crewmate.finishPrompt();
  await tick();
  expect(legacyStateOf(tasks.get(taskId))).toBe("idle");

  await supervisor.interruptCrewmate(taskId, "cancel");
  expect(legacyStateOf(tasks.get(taskId))).toBe("completed");
  expect(events.filter((e) => e.type === "task_finished").at(-1)).toMatchObject({
    type: "task_finished",
    status: "completed",
    title: "Ship it",
  });
});

